import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"周易口訣義 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"周易口訣義 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/koujueyi/036.md","filePath":"classics/koujueyi/036.md"}'),r={name:"classics/koujueyi/036.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><p>彖曰：大壯，大者壯也。剛以動，故壯。「大壯利貞」，大者正也。正大而天地之情可見矣。</p><p>象曰：雷在天上，大壯。君子以非禮弗履。</p><p>初九：壯於趾，徵兇，有孚。</p><p>象曰：「壯於趾」，其孚窮也。</p><p>九二：貞吉。</p><p>象曰：「九二貞吉」，以中也。</p><p>九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。</p><p>象曰：「小人用壯」，君子罔也。</p><p>九四：貞吉，悔亡。藩決不羸，壯於大，與之輹。</p><p>象曰：「藩決不羸」，尚往也。</p><p>六五：喪羊於易，無悔。</p><p>象曰：「喪羊於易」，位不當也。</p><p>上六：羝羊觸藩，不能退，不能遂，無攸利，艱則吉。</p><p>象曰：「不能退，不能遂」，不詳也。「艱則吉」，咎不長也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',16)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
